/// <summary>
/// PricingAttribute of table <c>EcoResProductCategory</c> field Category for level 7 i.e. Sub-Commodity..
/// </summary>
 [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
 [GUPPricingAttributeFieldsDiscovery(fieldStr(EcoResProductCategory, Category))]
internal class METGUPPricingAttributeEcoResProductCategorySubcommodity extends GUPPricingAttributeEcoResProductCategoryCategory implements GUPIPricingAttribute
{

}

Method.Source:
/// <summary>
/// Get value of the attribute
/// </summary>
/// <param name="_pricingObject">
/// The <c>Common</c> object that will be used to get the table record
/// </param>
/// <returns><c>anytype</c> object</returns>
public anytype getValueOfAttribute(Common _pricingObject)
{
    return this.getTableRecord(_pricingObject).Category;
}

/// <summary>
/// Retuns the name of the attribute
/// </summary>
/// <returns>name of attribute in string</returns>
public str getName()
{
    return "@MET:Subcommodity";
}

/// <summary>
/// Get attribte data type 
/// </summary>
/// <returns><c>AttributeDataType</c> object</returns>
public AttributeDataType getDataType()
{
    return AttributeDataType::Reference;
}

/// <summary>
/// Bug 296935: CB705 - Exclusive Product Hierarchies filter is not working to generate vendor rebate
/// Code copied from GUPPricingAttributeEcoResProductCategoryCategory, our custom class should extend it instead of copying code. Extensibility request to remove internal keyword to be raised.
/// </summary>
/// <param name="_query">
/// The <c>Query</c> object that the new ranges will be added to.
/// </param>
/// <param name="_value">
/// The <c>anytype</c> object that determines the category.
/// </param>
/// <param name="_qdbsMap">
/// The <c>Map</c> object that is used to identify the query build data source.
/// </param>
/// <returns><c>Query</c> object</returns>
public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    str queryRanges = this.copyOfConstructCategoryRanges(_value);
    if (queryRanges)
    {
        QueryBuildDataSource qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        // Bug 303887: CB705 - Exclusive Product Hierarchies filter is not working to cross different levels
        // As we are using 3 custom product category attributes, adding the range on the same field is handling it as OR condition instead of AND condition
        //qbds.addRange(fieldNum(EcoResCategory, CategoryHierarchy)).value(queryRanges);
        qbds.addRange(fieldNum(EcoResCategory, NestedSetLeft)).value(queryRanges);
    }
 
    return _query;
}

    /// <summary>
    /// Bug 296935: CB705 - Exclusive Product Hierarchies filter is not working to generate vendor rebate
    /// Code copied from GUPPricingAttributeEcoResProductCategoryCategory, our custom class should extend it instead of copying code. Extensibility request to remove internal keyword to be raised.
    /// </summary>
    /// <param name = "_value">Value</param>
    /// <returns>query ranges</returns>
    private str copyOfConstructCategoryRanges(anytype _value)
    {
        System.String valueStr, exclusionSign = '!';
        str queryRanges;
        boolean isExclusionOpt;

        List recIdList = strSplit(_value, ',');
        ListEnumerator enumerator = recIdList.getEnumerator();
        while (enumerator.moveNext())
        {
            valueStr = enumerator.current();
            isExclusionOpt = false;
            if (valueStr.StartsWith(exclusionSign))
            {
                valueStr = valueStr.Substring(1);
                isExclusionOpt = true;
            }

            int64 value = any2Int64(valueStr);
            EcoResCategory ecoResCategory = EcoResCategory::find(value);
            if (ecoResCategory)
            {
                if (queryRanges)
                {
                    queryRanges += isExclusionOpt ? ' && ' : ' || ';
                }

                if (isExclusionOpt)
                {
                    // (((NestedSetRight < ecoResCategory.NestedSetLeft) || (NestedSetLeft > ecoResCategory.NestedSetRight)) && (CategoryHierarchy == ecoResCategory.CategoryHierarchy))
                    queryRanges += strFmt('(((%1 < %2) || (%3 > %4)) && (%5 == %6))',
                                          fieldStr(EcoResCategory, NestedSetRight),
                                          any2Str(ecoResCategory.NestedSetLeft),
                                          fieldStr(EcoResCategory, NestedSetLeft),
                                          any2Str(ecoResCategory.NestedSetRight),
                                          fieldStr(EcoResCategory, CategoryHierarchy),
                                          int642Str(ecoResCategory.CategoryHierarchy));
                }
                else
                {
                    // (((NestedSetLeft >= ecoResCategory.NestedSetLeft) && (NestedSetRight <= ecoResCategory.NestedSetRight)) && (CategoryHierarchy == ecoResCategory.CategoryHierarchy))
                    queryRanges += strFmt('(((%1 >= %2) && (%3 <= %4)) && (%5 == %6))',
                                          fieldStr(EcoResCategory, NestedSetLeft),
                                          any2Str(ecoResCategory.NestedSetLeft),
                                          fieldStr(EcoResCategory, NestedSetRight),
                                          any2Str(ecoResCategory.NestedSetRight),
                                          fieldStr(EcoResCategory, CategoryHierarchy),
                                          int642Str(ecoResCategory.CategoryHierarchy));
                }
            }
        }

        return queryRanges;
    }

